SELECT "t3"."order_number", "t3"."invoice_id", "t3"."due", "t3"."open_amount", 'hold_ar' AS "route", 'overdue' AS "context"
FROM (SELECT "order_number", "invoice_id", "due", "amount" - "paid" AS "open_amount"
        FROM (SELECT "t0"."order_number", "t0"."customer", "t0"."channel", "t0"."fulfilling_warehouse", "t0"."value", "t0"."placed_date", "t0"."state", "invoice"."invoice_id", "invoice"."order_number" AS "order_number0", "invoice"."issued", "invoice"."due", "invoice"."amount", "invoice"."paid", "invoice"."status"
                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                        FROM "order"
                        WHERE "state" IN ('held', 'placed')) AS "t0"
                    INNER JOIN "invoice" ON "t0"."customer" = "invoice"."customer") AS "t1"
        WHERE "t1"."status" = 'open' AND "t1"."due" < :as_of) AS "t3"
    INNER JOIN (SELECT "order_number"
        FROM (SELECT "t32"."order_number", "t32"."customer", "t32"."channel", "t32"."fulfilling_warehouse", "t32"."value", "t32"."placed_date", "t32"."state", COALESCE("t32"."n_short", 0) AS "n_short", COALESCE("t32"."n_price", 0) AS "n_price", COALESCE("t38"."n_due", 0) AS "n_due"
                FROM (SELECT "t20"."order_number", "t20"."customer", "t20"."channel", "t20"."fulfilling_warehouse", "t20"."value", "t20"."placed_date", "t20"."state", "t20"."n_short", "t31"."n_price"
                        FROM (SELECT "t5"."order_number", "t5"."customer", "t5"."channel", "t5"."fulfilling_warehouse", "t5"."value", "t5"."placed_date", "t5"."state", "t19"."n_short"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t5"
                                    LEFT JOIN (SELECT "order_number", COUNT("line_no") AS "n_short"
                                        FROM (SELECT "t14"."order_number", "t14"."customer", "t14"."channel", "t14"."fulfilling_warehouse", "t14"."value", "t14"."placed_date", "t14"."state", "t14"."line_no", "t14"."item", "t14"."quantity", "t14"."unit_price", "t14"."ext_sales_price", "t14"."warehouse", "t14"."sold_date", "t14"."customer0", "t14"."channel0", "t14"."as_of_date", "t14"."quantity_on_hand", "t14"."_ttrp_g_n8_0", "t14"."_ttrp_g_n8_1", "t14"."_ttrp_d_n8", "t15"."warehouse" AS "warehouse0", "t15"."from_date", "t15"."to_date", "t15"."reason", COALESCE("t14"."quantity_on_hand", 0) AS "on_hand", "t15"."warehouse" IS NOT NULL AS "outage"
                                                FROM (SELECT "t8"."order_number", "t8"."customer", "t8"."channel", "t8"."fulfilling_warehouse", "t8"."value", "t8"."placed_date", "t8"."state", "t8"."line_no", "t8"."item", "t8"."quantity", "t8"."unit_price", "t8"."ext_sales_price", "t8"."warehouse", "t8"."sold_date", "t8"."customer0", "t8"."channel0", "t13"."as_of_date", "t13"."quantity_on_hand", "t13"."_ttrp_g_n8_0", "t13"."_ttrp_g_n8_1", "t13"."_ttrp_d_n8"
                                                        FROM (SELECT "t7"."order_number", "t7"."customer", "t7"."channel", "t7"."fulfilling_warehouse", "t7"."value", "t7"."placed_date", "t7"."state", "sales_line"."line_no", "sales_line"."item", "sales_line"."quantity", "sales_line"."unit_price", "sales_line"."ext_sales_price", "sales_line"."warehouse", "sales_line"."sold_date", "sales_line"."customer" AS "customer0", "sales_line"."channel" AS "channel0"
                                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                        FROM "order"
                                                                        WHERE "state" IN ('held', 'placed')) AS "t7"
                                                                    INNER JOIN "sales_line" ON "t7"."order_number" = "sales_line"."order_number") AS "t8"
                                                            LEFT JOIN (SELECT "t9"."as_of_date", "t9"."item", "t9"."warehouse", "t9"."quantity_on_hand", "t9"."_ttrp_g_n8_0", "t9"."_ttrp_g_n8_1", "t9"."_ttrp_d_n8"
                                                                FROM (SELECT "as_of_date", "item", "warehouse", "quantity_on_hand", CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n8_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n8_1", CASE WHEN "as_of_date" IS NULL THEN 'n' ELSE 'v' || CAST("as_of_date" AS VARCHAR) END AS "_ttrp_d_n8"
                                                                        FROM "inventory") AS "t9"
                                                                    INNER JOIN (SELECT CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n8_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n8_1", CASE WHEN MAX("as_of_date") IS NULL THEN 'n' ELSE 'v' || CAST(MAX("as_of_date") AS VARCHAR) END AS "_ttrp_dm_n8"
                                                                        FROM "inventory"
                                                                        GROUP BY CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END, CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END) AS "t12" ON "t9"."_ttrp_g_n8_0" = "t12"."_ttrp_g_n8_0" AND "t9"."_ttrp_g_n8_1" = "t12"."_ttrp_g_n8_1" AND "t9"."_ttrp_d_n8" = "t12"."_ttrp_dm_n8") AS "t13" ON "t8"."item" = "t13"."item" AND "t8"."warehouse" = "t13"."warehouse") AS "t14"
                                                    LEFT JOIN (SELECT *
                                                        FROM "warehouse_outage"
                                                        WHERE "from_date" <= :as_of AND "to_date" >= :as_of) AS "t15" ON "t14"."warehouse" = "t15"."warehouse") AS "t16"
                                        WHERE "t16"."outage" OR "t16"."on_hand" < "t16"."quantity"
                                        GROUP BY "order_number") AS "t19" ON "t5"."order_number" = "t19"."order_number") AS "t20"
                            LEFT JOIN (SELECT "order_number0" AS "order_number", COUNT("line_no0") AS "n_price"
                                FROM (SELECT "t23"."order_number", "t23"."line_no", "t23"."item", "t23"."unit_price", "t23"."customer", "t23"."channel", "t23"."placed_date", "t27"."order_number" AS "order_number0", "t27"."line_no" AS "line_no0", "t27"."price"
                                        FROM (SELECT "sales_line0"."order_number", "sales_line0"."line_no", "sales_line0"."item", "sales_line0"."unit_price", "t22"."customer", "t22"."channel", "t22"."placed_date"
                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                        FROM "order"
                                                        WHERE "state" IN ('held', 'placed')) AS "t22"
                                                    INNER JOIN "sales_line" AS "sales_line0" ON "t22"."order_number" = "sales_line0"."order_number") AS "t23"
                                            INNER JOIN (SELECT "t26"."order_number", "t26"."line_no", COALESCE("customer_price"."price", "price_list"."price") AS "price"
                                                FROM (SELECT "sales_line1"."order_number", "sales_line1"."line_no", "sales_line1"."item", "sales_line1"."unit_price", "t25"."customer", "t25"."channel", "t25"."placed_date"
                                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                FROM "order"
                                                                WHERE "state" IN ('held', 'placed')) AS "t25"
                                                            INNER JOIN "sales_line" AS "sales_line1" ON "t25"."order_number" = "sales_line1"."order_number") AS "t26"
                                                    LEFT JOIN "customer_price" ON "t26"."item" = "customer_price"."item" AND "t26"."customer" = "customer_price"."customer" AND "t26"."placed_date" >= "customer_price"."valid_from" AND ("customer_price"."valid_to" IS NULL OR "t26"."placed_date" <= "customer_price"."valid_to")
                                                    LEFT JOIN "price_list" ON "t26"."item" = "price_list"."item" AND "t26"."channel" = "price_list"."channel" AND "t26"."placed_date" >= "price_list"."valid_from" AND ("price_list"."valid_to" IS NULL OR "t26"."placed_date" <= "price_list"."valid_to")) AS "t27" ON "t23"."order_number" = "t27"."order_number" AND "t23"."line_no" = "t27"."line_no") AS "t28"
                                WHERE "t28"."price" IS NULL OR ABS("t28"."unit_price" - "t28"."price") > :tolerance
                                GROUP BY "order_number0") AS "t31" ON "t20"."order_number" = "t31"."order_number") AS "t32"
                    LEFT JOIN (SELECT "order_number", COUNT("invoice_id") AS "n_due"
                        FROM (SELECT "t34"."order_number", "t34"."customer", "t34"."channel", "t34"."fulfilling_warehouse", "t34"."value", "t34"."placed_date", "t34"."state", "invoice0"."invoice_id", "invoice0"."order_number" AS "order_number0", "invoice0"."issued", "invoice0"."due", "invoice0"."amount", "invoice0"."paid", "invoice0"."status"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t34"
                                    INNER JOIN "invoice" AS "invoice0" ON "t34"."customer" = "invoice0"."customer") AS "t35"
                        WHERE "t35"."status" = 'open' AND "t35"."due" < :as_of
                        GROUP BY "order_number") AS "t38" ON "t32"."order_number" = "t38"."order_number") AS "t39"
        WHERE "t39"."n_due" > 0
        GROUP BY "order_number") AS "t42" ON "t3"."order_number" = "t42"."order_number"
